import os, pty, sys, select, time
def run(cwd, args, answers, timeout=15, cols=100, rows=40, env=None):
    pid, fd = pty.fork()
    if pid == 0:
        os.chdir(cwd)
        os.environ['TERM']='xterm-256color'
        os.environ['LINES']=str(rows); os.environ['COLUMNS']=str(cols)
        for k,v in (env or {}).items():
            if v is None: os.environ.pop(k,None)
            else: os.environ[k]=v
        os.execv('/workspace/executable', ['zk']+args)
    import fcntl, termios, struct
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out=b''; ai=0; t0=time.time(); pending=b''
    while time.time()-t0 < timeout:
        r,_,_=select.select([fd],[],[],0.25)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d; pending+=d
            while b'\x1b[6n' in pending:
                pending=pending.replace(b'\x1b[6n',b'',1)
                os.write(fd,b'\x1b[%d;1R'%rows)
            continue
        if ai < len(answers):
            os.write(fd,answers[ai]); ai+=1; t0=time.time()
        else: break
    time.sleep(0.3)
    while True:
        r,_,_=select.select([fd],[],[],0.3)
        if not r: break
        try: d=os.read(fd,65536)
        except OSError: break
        if not d: break
        out+=d
    st=0
    try: _,st=os.waitpid(pid,0)
    except Exception: pass
    return out, os.waitstatus_to_exitcode(st) if st is not None else None
if __name__=='__main__':
    cwd=sys.argv[1]; args=[]; answers=[]; env={}; mode='a'
    for a in sys.argv[2:]:
        if a=='--IN': mode='i'; continue
        if a.startswith('--ENV='):
            k,_,v=a[6:].partition('='); env[k]=v; continue
        if a.startswith('--UNSET='): env[a[8:]]=None; continue
        if mode=='a': args.append(a)
        else: answers.append(a.encode().decode('unicode_escape').encode('latin1'))
    out,code=run(cwd,args,answers,env=env)
    sys.stdout.buffer.write(out); sys.stdout.buffer.flush()
    sys.stderr.write('\n[EXITCODE=%s]\n'%code)
PYEOF
